#!/usr/bin/env python3
import tempfile
from pathlib import Path


def assert_script_copies_cover_script_family(script_dir, script_copies, label, patterns):
    copy_set = set(script_copies)
    missing = []
    for pattern in patterns:
        for path in sorted(script_dir.glob(pattern)):
            if path.name not in copy_set:
                missing.append(path.name)
    if missing:
        raise AssertionError(f'missing {label} fixture script copies: {", ".join(missing)}')


def write_repo(repo, script_file):
    workflows = repo / '.github' / 'workflows'
    setup_action = repo / '.github' / 'actions' / 'setup-windows-deps'
    profiling_action = repo / '.github' / 'actions' / 'build-x265-profiling'
    scripts = repo / '.github' / 'scripts'
    patches = repo / '.github' / 'patches'
    workflows.mkdir(parents=True)
    setup_action.mkdir(parents=True)
    profiling_action.mkdir(parents=True)
    scripts.mkdir(parents=True)
    patches.mkdir(parents=True)

    script_path = Path(script_file).resolve()
    github_dir = script_path.parents[1]

    workflow_files = (
        'build.yml',
        'build-profiling.yml',
        'build-pgo.yml',
        'update-deps.yml',
    )
