def replace_text(path, old, new, count=1):
    text = path.read_text()
    if old not in text:
        raise AssertionError(f'missing text {old!r} in {path}')
    path.write_text(text.replace(old, new, count))


def case(modifier, expected, check):
    return {
        'modifier': modifier,
        'expected': expected,
        'check': check,
    }


